import{_ as e,c as t,o as r,ae as o}from"./chunks/framework.DMK_uHmU.js";const h=JSON.parse('{"title":"Security Settings Configuration Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Administration/Manage/Global-Settings/security.md","filePath":"Administration/Manage/Global-Settings/security.md"}'),n={name:"Administration/Manage/Global-Settings/security.md"};function a(l,i,s,u,d,c){return r(),t("div",null,i[0]||(i[0]=[o('<h1 id="security-settings-configuration-guide" tabindex="-1">Security Settings Configuration Guide <a class="header-anchor" href="#security-settings-configuration-guide" aria-label="Permalink to &quot;Security Settings Configuration Guide&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#security-settings-configuration-guide">Security Settings Configuration Guide</a><ul><li><a href="#table-of-contents">Table of Contents</a></li><li><a href="#introduction">Introduction</a></li><li><a href="#accessing-security-settings">Accessing Security Settings</a></li><li><a href="#multi-factor-authentication">Multi-Factor Authentication</a></li><li><a href="#identity-providers">Identity Providers</a><ul><li><a href="#sairis-native-security">Sairis Native Security</a></li><li><a href="#oidc-integration">OIDC Integration</a></li><li><a href="#saml-20-integration">SAML 2.0 Integration</a></li></ul></li><li><a href="#password-policy-configuration">Password Policy Configuration</a></li><li><a href="#oidc-provider-configuration">OIDC Provider Configuration</a><ul><li><a href="#basic-configuration">Basic Configuration</a></li><li><a href="#endpoint-management">Endpoint Management</a></li><li><a href="#attribute-mapping">Attribute Mapping</a></li><li><a href="#identity-provider-identifiers">Identity Provider Identifiers</a></li></ul></li><li><a href="#saml-provider-configuration">SAML Provider Configuration</a><ul><li><a href="#basic-configuration-1">Basic Configuration</a></li><li><a href="#metadata-document">Metadata Document</a></li><li><a href="#saml-signing-and-encryption">SAML Signing and Encryption</a></li><li><a href="#attribute-mapping-1">Attribute Mapping</a></li><li><a href="#saml-identifiers">SAML Identifiers</a></li></ul></li><li><a href="#best-practices">Best Practices</a></li><li><a href="#troubleshooting">Troubleshooting</a></li></ul></li></ul><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The Security Settings component allows administrators to configure authentication methods, multi-factor authentication (MFA), and identity provider integrations for your organization. These settings determine how users authenticate with the system and what security measures are required for account access.</p><h2 id="accessing-security-settings" tabindex="-1">Accessing Security Settings <a class="header-anchor" href="#accessing-security-settings" aria-label="Permalink to &quot;Accessing Security Settings&quot;">​</a></h2><p>The Security Settings component is accessible to users with specific roles:</p><ul><li>Admin</li><li>Content</li><li>Manager</li></ul><p>To access this component, navigate to the Tenant Settings section in the administration interface.</p><h2 id="multi-factor-authentication" tabindex="-1">Multi-Factor Authentication <a class="header-anchor" href="#multi-factor-authentication" aria-label="Permalink to &quot;Multi-Factor Authentication&quot;">​</a></h2><p>Multi-Factor Authentication (MFA) adds an extra layer of security by requiring users to provide a second verification method beyond their password. The system supports SMS-based MFA, sending a one-time password (OTP) to the user&#39;s mobile phone.</p><p>Three MFA options are available:</p><ol><li><p><strong>MFA Off</strong>:</p><ul><li>No additional authentication required beyond username/password</li><li>Lowest security option</li><li>Fastest login experience</li></ul></li><li><p><strong>MFA On (Everyone)</strong>:</p><ul><li>All users must provide a mobile phone number</li><li>All users must verify via SMS code when logging in on new devices</li><li>Highest security option</li><li>Ensures consistent security policy across the organization</li></ul></li><li><p><strong>MFA Optional (Per User)</strong>:</p><ul><li>Individual users can be configured for MFA</li><li>MFA can be enabled for specific users or roles</li><li>Balance between security and flexibility</li><li>Allows gradual rollout of MFA</li></ul></li></ol><h2 id="identity-providers" tabindex="-1">Identity Providers <a class="header-anchor" href="#identity-providers" aria-label="Permalink to &quot;Identity Providers&quot;">​</a></h2><p>The system supports three authentication approaches:</p><h3 id="sairis-native-security" tabindex="-1">Sairis Native Security <a class="header-anchor" href="#sairis-native-security" aria-label="Permalink to &quot;Sairis Native Security&quot;">​</a></h3><p>The default authentication method provided by the platform:</p><ul><li>Built-in user management</li><li>Password-based authentication</li><li>Configurable password policies</li><li>Support for MFA</li><li>Can act as an OIDC provider for other applications</li></ul><h3 id="oidc-integration" tabindex="-1">OIDC Integration <a class="header-anchor" href="#oidc-integration" aria-label="Permalink to &quot;OIDC Integration&quot;">​</a></h3><p>Connect to an existing OpenID Connect (OIDC) provider:</p><ul><li>Single Sign-On (SSO) with existing identity systems</li><li>Delegate authentication to external providers</li><li>Support for major providers like Google, Microsoft, Okta, Auth0</li><li>Attribute mapping for user profile information</li></ul><h3 id="saml-2-0-integration" tabindex="-1">SAML 2.0 Integration <a class="header-anchor" href="#saml-2-0-integration" aria-label="Permalink to &quot;SAML 2.0 Integration&quot;">​</a></h3><p>Connect to an existing SAML 2.0 provider:</p><ul><li>Enterprise-grade SSO integration</li><li>Support for legacy identity systems</li><li>Digital signing and encryption options</li><li>Attribute mapping for user profile information</li></ul><h2 id="password-policy-configuration" tabindex="-1">Password Policy Configuration <a class="header-anchor" href="#password-policy-configuration" aria-label="Permalink to &quot;Password Policy Configuration&quot;">​</a></h2><p>When using Sairis Native Security, you can configure comprehensive password policies:</p><ol><li><p><strong>Password Minimum Length</strong>:</p><ul><li>Set the minimum number of characters required</li><li>Range: 6-99 characters</li><li>Recommended: 8 or more characters</li><li>Default: 8 characters</li></ul></li><li><p><strong>Temporary Password Validity</strong>:</p><ul><li>Number of days before temporary passwords expire</li><li>Range: 0-365 days</li><li>Default: 30 days</li><li>Setting to 0 means passwords never expire</li></ul></li><li><p><strong>Password Strength Requirements</strong>:</p><ul><li><strong>Require Lowercase Letters</strong>: When enabled, passwords must include at least one lowercase letter</li><li><strong>Require Uppercase Letters</strong>: When enabled, passwords must include at least one uppercase letter</li><li><strong>Require Numbers</strong>: When enabled, passwords must include at least one numeric character</li><li><strong>Require Special Characters</strong>: When enabled, passwords must include at least one special character</li></ul></li></ol><p>All strength requirements are enabled by default, providing maximum security.</p><h2 id="oidc-provider-configuration" tabindex="-1">OIDC Provider Configuration <a class="header-anchor" href="#oidc-provider-configuration" aria-label="Permalink to &quot;OIDC Provider Configuration&quot;">​</a></h2><p>When &quot;Identity Provider - OIDC&quot; is selected, you must configure the OIDC integration:</p><h3 id="basic-configuration" tabindex="-1">Basic Configuration <a class="header-anchor" href="#basic-configuration" aria-label="Permalink to &quot;Basic Configuration&quot;">​</a></h3><ol><li><p><strong>Provider Name</strong>:</p><ul><li>Friendly name for the identity provider</li><li>Used in administration interfaces</li><li>Example: &quot;Corporate OIDC&quot;, &quot;Google SSO&quot;, &quot;Okta&quot;</li></ul></li><li><p><strong>Client ID</strong>:</p><ul><li>Identifier issued by your OIDC provider</li><li>Uniquely identifies your application with the provider</li><li>Obtained when registering with the identity provider</li></ul></li><li><p><strong>Client Secret</strong>:</p><ul><li>Secret key issued by your OIDC provider</li><li>Should be kept confidential</li><li>Used to authenticate your application with the provider</li></ul></li><li><p><strong>Authorized Scopes</strong>:</p><ul><li>OAuth 2.0 scopes that determine what information is requested</li><li>Default: &quot;openid&quot; (minimum required)</li><li>Additional options: profile, email, phone, etc.</li><li>Multiple scopes should be space-separated</li></ul></li><li><p><strong>Attribute Request Method</strong>:</p><ul><li>HTTP method used to retrieve user attributes</li><li>Options: GET or POST</li><li>Default: GET</li><li>Should match the configuration of your provider</li></ul></li></ol><h3 id="endpoint-management" tabindex="-1">Endpoint Management <a class="header-anchor" href="#endpoint-management" aria-label="Permalink to &quot;Endpoint Management&quot;">​</a></h3><p>Two options for configuring endpoints:</p><ol><li><p><strong>Auto Fill via Issuer URL</strong>:</p><ul><li>Automatically discovers endpoints using OpenID Connect discovery</li><li>Requires only the Issuer URL to be provided</li><li>System retrieves all endpoint URLs from the provider&#39;s discovery document</li><li>Recommended for most configurations</li></ul></li><li><p><strong>Manually Configure Endpoints</strong>:</p><ul><li>Allows direct specification of all endpoint URLs</li><li>Required fields when selected: <ul><li><strong>Authorization Endpoint</strong>: URL for user authentication</li><li><strong>Token Endpoint</strong>: URL for token exchange</li><li><strong>UserInfo Endpoint</strong>: URL for retrieving user attributes</li><li><strong>JWKS URI Endpoint</strong>: URL for JSON Web Key Set (for signature verification)</li></ul></li><li>All URLs must include the full path, including &quot;https://&quot;</li></ul></li></ol><h3 id="attribute-mapping" tabindex="-1">Attribute Mapping <a class="header-anchor" href="#attribute-mapping" aria-label="Permalink to &quot;Attribute Mapping&quot;">​</a></h3><p>Maps OIDC attributes to user profile fields:</p><ol><li><strong>Given Name</strong>: Maps to user&#39;s first name</li><li><strong>Family Name</strong>: Maps to user&#39;s last name</li><li><strong>Username</strong>: Maps to login identifier</li><li><strong>Preferred Username</strong>: Maps to display name</li><li><strong>Email</strong>: Maps to user&#39;s email address</li><li><strong>Phone Number</strong>: Maps to user&#39;s mobile phone</li></ol><p>For each field, you must specify the corresponding attribute name from your OIDC provider.</p><h3 id="identity-provider-identifiers" tabindex="-1">Identity Provider Identifiers <a class="header-anchor" href="#identity-provider-identifiers" aria-label="Permalink to &quot;Identity Provider Identifiers&quot;">​</a></h3><p>Optional domain identifiers for automatic provider selection:</p><ul><li>Allows routing users to the correct identity provider based on email domain</li><li>Enter domain names that should be associated with this provider</li><li>Example: &quot;example.com&quot; would route all users with @example.com emails</li><li>Multiple domains can be entered (one per line)</li></ul><h2 id="saml-provider-configuration" tabindex="-1">SAML Provider Configuration <a class="header-anchor" href="#saml-provider-configuration" aria-label="Permalink to &quot;SAML Provider Configuration&quot;">​</a></h2><p>When &quot;Identity Provider - SAML 2.0&quot; is selected, you must configure the SAML integration:</p><h3 id="basic-configuration-1" tabindex="-1">Basic Configuration <a class="header-anchor" href="#basic-configuration-1" aria-label="Permalink to &quot;Basic Configuration&quot;">​</a></h3><ol><li><p><strong>Provider Name</strong>:</p><ul><li>Friendly name for the SAML provider</li><li>Used in administration interfaces</li><li>Example: &quot;Corporate SAML&quot;, &quot;Azure AD&quot;, &quot;ADFS&quot;</li></ul></li><li><p><strong>Add Sign-out Flow</strong>:</p><ul><li>When enabled, signing out from the application also signs out from the SAML provider</li><li>Creates a more seamless experience</li><li>Toggle on/off based on requirements</li></ul></li><li><p><strong>IdP-initiated SAML Sign-in</strong>:</p><ul><li><strong>Require SP-initiated SAML assertions</strong> (Recommended): More secure, requires sign-in to start from Sairis</li><li><strong>Accept SP-initiated and IdP-initiated SAML assertions</strong>: More flexible, allows sign-in to start from the identity provider</li></ul></li></ol><h3 id="metadata-document" tabindex="-1">Metadata Document <a class="header-anchor" href="#metadata-document" aria-label="Permalink to &quot;Metadata Document&quot;">​</a></h3><p>SAML metadata document from your identity provider:</p><ul><li>XML document containing provider configuration details</li><li>Includes certificates, endpoints, and entity IDs</li><li>Paste the full XML document into the text area</li><li>Required for establishing trust with the identity provider</li></ul><h3 id="saml-signing-and-encryption" tabindex="-1">SAML Signing and Encryption <a class="header-anchor" href="#saml-signing-and-encryption" aria-label="Permalink to &quot;SAML Signing and Encryption&quot;">​</a></h3><p>Advanced security options:</p><ol><li><p><strong>Sign SAML Requests</strong>:</p><ul><li>When enabled, all SAML requests are digitally signed</li><li>Adds security by proving request authenticity</li><li>Requires trust configuration on the identity provider</li></ul></li><li><p><strong>Require Encrypted SAML Assertions</strong>:</p><ul><li>When enabled, requires all SAML assertions to be encrypted</li><li>Enhances security by protecting data in transit</li><li>Requires proper key configuration</li></ul></li></ol><h3 id="attribute-mapping-1" tabindex="-1">Attribute Mapping <a class="header-anchor" href="#attribute-mapping-1" aria-label="Permalink to &quot;Attribute Mapping&quot;">​</a></h3><p>Maps SAML attributes to user profile fields:</p><ol><li><strong>Given Name</strong>: Maps to user&#39;s first name</li><li><strong>Family Name</strong>: Maps to user&#39;s last name</li><li><strong>Username</strong>: Maps to login identifier</li><li><strong>Preferred Username</strong>: Maps to display name</li><li><strong>Email</strong>: Maps to user&#39;s email address</li><li><strong>Phone Number</strong>: Maps to user&#39;s mobile phone</li></ol><p>For each field, you must specify the corresponding attribute name from your SAML provider.</p><h3 id="saml-identifiers" tabindex="-1">SAML Identifiers <a class="header-anchor" href="#saml-identifiers" aria-label="Permalink to &quot;SAML Identifiers&quot;">​</a></h3><p>Optional domain identifiers for automatic provider selection:</p><ul><li>Allows routing users to the correct identity provider based on email domain</li><li>Enter domain names that should be associated with this provider</li><li>Example: &quot;example.com&quot; would route all users with @example.com emails</li><li>Multiple domains can be entered (one per line)</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><p>For optimal security configuration:</p><ol><li><p><strong>Multi-Factor Authentication</strong>:</p><ul><li>Enable MFA for all users when possible</li><li>At minimum, require MFA for administrative users</li><li>Ensure users have updated mobile phone numbers</li></ul></li><li><p><strong>Password Policies</strong>:</p><ul><li>Use minimum length of 12+ characters for best security</li><li>Enable all character type requirements (upper, lower, number, special)</li><li>Set reasonable temporary password expiration (7-14 days)</li></ul></li><li><p><strong>Identity Provider Integration</strong>:</p><ul><li>Use HTTPS for all endpoint URLs</li><li>Keep client secrets secure</li><li>Test the integration thoroughly before full deployment</li><li>Enable signing and encryption for SAML when supported</li></ul></li><li><p><strong>Attribute Mapping</strong>:</p><ul><li>Verify attribute names exactly match those provided by your identity provider</li><li>Test with sample users before full deployment</li><li>Consider required vs. optional attributes in your provider</li></ul></li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Issue</strong>: Users cannot authenticate with external identity provider</p><ul><li>Verify client ID and secret are correct</li><li>Check that all endpoint URLs are accessible</li><li>Ensure attribute mappings match exactly what the provider sends</li><li>Review identity provider logs for error details</li></ul><p><strong>Issue</strong>: MFA not working properly</p><ul><li>Verify user has a valid mobile phone number in their profile</li><li>Check SMS service configuration in system settings</li><li>Ensure proper country code is included with phone numbers</li></ul><p><strong>Issue</strong>: Password policy not enforced</p><ul><li>Verify Sairis Native Security is selected as the identity provider</li><li>Check that policy settings are saved correctly</li><li>Test with a new user account or password reset</li></ul><p><strong>Issue</strong>: SAML metadata document rejected</p><ul><li>Ensure the document is valid XML</li><li>Check for any extraneous characters or encoding issues</li><li>Verify the document is from a trusted provider</li><li>Confirm the document includes all required elements</li></ul><p><strong>Issue</strong>: &quot;Provider not found&quot; error during login</p><ul><li>Check identifiers configuration for domain routing</li><li>Verify the email domain matches the configured identifiers</li><li>Ensure the identity provider is properly activated</li></ul><hr><p>For additional assistance with security configuration, please contact your system administrator or refer to the advanced administration documentation.</p>',75)]))}const g=e(n,[["render",a]]);export{h as __pageData,g as default};
